package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Cow;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ArcaneLampAudit {
 static final BlockPos POS=FocalAudit.BASE.offset(0,1,88),GROW=POS.east(6),FERT=POS.east(14),CROP=GROW.south(2);static int ticks;static volatile boolean prepared,finished,lighting;static ArcaneLamps.LampEntity growth,fertility;static int lights;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_LAMPS FAIL "+s);System.out.println("TC4_LAMPS PASS "+s);}
 static void jar(net.minecraft.server.level.ServerLevel l,BlockPos p,Aspect a,int n){l.setBlock(p,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(p);jar.state.aspect=a;jar.state.amount=n;jar.changed();}
 static void prepare(ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.removeAllEffects();p.getInventory().clearContent();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");
  for(var cow:l.getEntitiesOfClass(Cow.class,new AABB(POS).inflate(30)))cow.discard();
  for(int x=-17;x<=20;x++)for(int z=-17;z<=17;z++)for(int y=-2;y<=8;y++)l.setBlock(POS.offset(x,y,z),y==-2||y==8||x==-17||x==20||z==-17||z==17?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  l.setBlock(POS,ArcaneLamps.LAMP.get().defaultBlockState().setValue(ArcaneLamps.LampBlock.LIT,true),3);var lamp=(ArcaneLamps.LampEntity)l.getBlockEntity(POS);var source=ArcaneLamps.LIGHT.get().defaultBlockState();check(source.getShape(l,POS).isEmpty()&&source.getCollisionShape(l,POS).isEmpty()&&source.getLightEmission(l,POS)==15,"light cells emit15 without selection or collision");
  l.setBlock(GROW,ArcaneLamps.GROWTH.get().defaultBlockState(),3);growth=(ArcaneLamps.LampEntity)l.getBlockEntity(GROW);jar(l,GROW.below(),Aspect.PLANT,4);
  l.setBlock(CROP.below(),Blocks.FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,7),3);l.setBlock(CROP,Blocks.WHEAT.defaultBlockState(),3);growth.checklist.clear();growth.checklist.add(CROP.above(6));growth.cursor=0;
  for(int i=0;i<8;i++)ArcaneLamps.LampEntity.tick(l,GROW,l.getBlockState(GROW),growth);check(growth.charges>0&&growth.reserve,"growth draws one100charge unit plus one reserve unit");var saved=growth.saveWithFullMetadata(l.registryAccess());var copy=new ArcaneLamps.LampEntity(GROW,l.getBlockState(GROW));copy.loadWithComponents(saved,l.registryAccess());check(copy.charges==growth.charges&&copy.reserve,"growth charges and reserve persist");
  check(!growth.isPlant(GROW.west()),"air is not a plant");l.setBlock(GROW.west(),Blocks.GRASS_BLOCK.defaultBlockState(),3);check(!growth.isPlant(GROW.west()),"original grass material excluded even if bonemealable");l.removeBlock(GROW.west(),false);
  l.setBlock(CROP,Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7),3);check(growth.grown(CROP),"fully grown wheat skipped");l.setBlock(CROP,Blocks.WHEAT.defaultBlockState(),3);
  growth.charges=1;growth.reserve=false;growth.checklist.clear();growth.checklist.add(CROP.above(6));growth.cursor=0;growth.updatePlant();check(growth.charges==0&&growth.pending.equals(CROP),"growth spends one charge scheduling next-tick crop update, safe last scan column");
  growth.checklist.clear();for(int i=0;i<100;i++)growth.checklist.add(CROP.above(6));growth.cursor=0;
  l.setBlock(FERT,ArcaneLamps.FERTILITY.get().defaultBlockState(),3);fertility=(ArcaneLamps.LampEntity)l.getBlockEntity(FERT);fertility.charges=2;for(int i=0;i<2;i++){var cow=new Cow(EntityType.COW,l);cow.moveTo(FERT.getX()+i*.8,FERT.getY()-1,FERT.getZ()+2);l.addFreshEntity(cow);}fertility.updateAnimals();check(fertility.charges==0&&l.getEntitiesOfClass(Cow.class,new AABB(FERT).inflate(7)).stream().allMatch(Cow::isInLove),"two adult cows enter love for exactly2Victus");
  // Eight same-class animals prevent breeding, including babies/cooldown animals in original population count.
  for(var cow:l.getEntitiesOfClass(Cow.class,new AABB(FERT).inflate(7)))cow.resetLove();for(int i=0;i<6;i++){var cow=new Cow(EntityType.COW,l);cow.moveTo(FERT.getX()+i*.3,FERT.getY()-1,FERT.getZ()+3);l.addFreshEntity(cow);}fertility.charges=4;fertility.updateAnimals();check(fertility.charges==4,"eight same-class animals block fertility");for(var cow:l.getEntitiesOfClass(Cow.class,new AABB(FERT).inflate(7)))cow.discard();for(int i=0;i<2;i++){var cow=new Cow(EntityType.COW,l);cow.moveTo(FERT.getX()+i*.8,FERT.getY()-1,FERT.getZ()+2);l.addFreshEntity(cow);}fertility.charges=0;jar(l,FERT.below(),Aspect.LIFE,4);
  var r=ArcaneRecipes.entries().stream().filter(v->v.key().equals("ArcaneLamp")).findFirst().orElseThrow();var grid=r.ingredients().stream().map(i->i.isEmpty()?ItemStack.EMPTY:i.getItems()[0].copy()).toList();check(r.matches(grid,Set.of("ARCANELAMP"))&&!r.matches(grid,Set.of()),"actual original arcane lamp recipe research gate");for(var key:List.of("LampGrowth","LampFertility")){var recipe=InfusionItemRecipes.all().stream().filter(v->v.key().equals(key)).findFirst().orElseThrow();check(recipe.components().size()==6&&recipe.aspects().visSize()==40&&recipe.instability()==4,"original six-component40essentia infusion "+key);}
  p.connection.teleport(GROW.getX()+5,GROW.getY()+3,GROW.getZ()-7,35,20);p.getInventory().setItem(0,new ItemStack(ArcaneLamps.LAMP.get()));p.getInventory().setItem(1,new ItemStack(ArcaneLamps.GROWTH.get()));p.getInventory().setItem(2,new ItemStack(ArcaneLamps.FERTILITY.get()));p.getInventory().selected=8;prepared=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.lampsAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==125)server.execute(()->{var l=server.overworld();for(int x=-15;x<=15;x++)for(int y=-2;y<=7;y++)for(int z=-15;z<=15;z++)if(l.getBlockState(POS.offset(x,y,z)).is(ArcaneLamps.LIGHT.get()))lights++;check(lights>0,"natural dark room receives invisible area lights after lighting engine settles");lighting=true;});if(ticks==130){check(lighting,"natural area lighting complete");check(prepared,"server setup complete");check(mc.getResourceManager().getResource(AlchemyContent.id("textures/models/bore.png")).isPresent(),"original nozzle texture imported with legal lowercase resource path");for(var pos:List.of(POS,GROW,FERT)){var state=mc.level.getBlockState(pos);check(mc.getBlockRenderer().getBlockModel(state).getQuads(state,null,net.minecraft.util.RandomSource.create()).stream().noneMatch(q->q.getSprite().contents().name().getPath().equals("missingno")),"lamp model textures present "+pos);}LiquidDeathAudit.shot(mc,"arcane-lamps.png");}if(ticks==450)server.execute(()->{var l=server.overworld();check(l.getEntitiesOfClass(Cow.class,new AABB(FERT).inflate(7)).stream().anyMatch(Cow::isBaby),"actual natural animal AI produces calf under fertility lamp");check(((WardedJarEntity)l.getBlockEntity(FERT.below())).state.amount==0,"fertility naturally draws exactly4Victus from jar");check(l.getBlockState(CROP).getValue(CropBlock.AGE)>0,"actual scheduled random growth advances wheat");l.removeBlock(POS,false);int remaining=0;for(int x=-15;x<=15;x++)for(int y=-15;y<=15;y++)for(int z=-15;z<=15;z++)if(l.getBlockState(POS.offset(x,y,z)).is(ArcaneLamps.LIGHT.get()))remaining++;check(remaining==0,"breaking normal lamp clears all nearby invisible lights");finished=true;});if(ticks==460){check(finished,"native lamps complete");LiquidDeathAudit.shot(mc,"arcane-lamps-grown.png");var inv=mc.player.getInventory();mc.setScreen(new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty()));}if(ticks>=470&&ticks<=490&&ticks%10==0)((ThaumonomiconScreen)mc.screen).auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(List.of("ARCANELAMP","LAMPGROWTH","LAMPFERTILITY").get((ticks-470)/10)),0);if(ticks>=475&&ticks<=495&&ticks%10==5)LiquidDeathAudit.shot(mc,"arcane-lamp-book-"+(ticks-475)/10+".png");if(ticks==500)mc.stop();}
}
